+
+double dubins_segment_length(DubinsPath * path, int i)
+{
+  if( (i < 0) || (i > 2) ) {
+    return INFINITY;
+  }
+  return path->param[i] * path->rho;
+}
+
+double dubins_segment_length_normalized(DubinsPath * path, int i)
+{
+  if( (i < 0) || (i > 2) ) {
+    return INFINITY;
+  }
+  return path->param[i];
+}
+
+DubinsPathType dubins_path_type(DubinsPath * path)
+{
+  return path->type;
+}
+
+void dubins_segment(double t, double qi[3], double qt[3], SegmentType type)
+{
+  double st = sin(qi[2]);
+  double ct = cos(qi[2]);
+  if(type == L_SEG) {
+    qt[0] = +sin(qi[2] + t) - st;
+    qt[1] = -cos(qi[2] + t) + ct;
+    qt[2] = t;
+  } else if(type == R_SEG) {
+    qt[0] = -sin(qi[2] - t) + st;
+    qt[1] = +cos(qi[2] - t) - ct;
+    qt[2] = -t;
+  } else if(type == S_SEG) {
+    qt[0] = ct * t;
+    qt[1] = st * t;
+    qt[2] = 0.0;
+  }
+  qt[0] += qi[0];
+  qt[1] += qi[1];
+  qt[2] += qi[2];
+}
+
+int dubins_path_sample(DubinsPath * path, double t, double q[3])
+{
+    /* tprime is the normalised variant of the parameter t */
+  double tprime = t / path->rho;
+  double qi[3];   /* The translated initial configuration */
+  double q1[3];   /* end-of segment 1 */
+  double q2[3];   /* end-of segment 2 */
+  const SegmentType * types = DIRDATA[path->type];
+  double p1, p2;
+
+  if(t < 0 || t > dubins_path_length(path) ) {
+    return EDUBPARAM;
+  }
+
+    /* initial configuration */
+  qi[0] = 0.0;
+  qi[1] = 0.0;
+  qi[2] = path->qi[2];
+
+    /* generate the target configuration */
+  p1 = path->param[0];
+  p2 = path->param[1];
+  dubins_segment(p1, qi, q1, types[0]);
+  dubins_segment(p2, q1, q2, types[1]);
+  if(tprime < p1) {
+    dubins_segment(tprime, qi, q, types[0]);
+  } else if(tprime < (p1 + p2) ) {
+    dubins_segment(tprime - p1, q1, q, types[1]);
+  } else {
+    dubins_segment(tprime - p1 - p2, q2, q, types[2]);
+  }
+
+    /* scale the target configuration, translate back to the original starting point */
+  q[0] = q[0] * path->rho + path->qi[0];
+  q[1] = q[1] * path->rho + path->qi[1];
+  q[2] = mod2pi(q[2]);
+
+  return EDUBOK;
+}
